import type { ContentSection, Lesson } from '../types';
import type { SourceId } from './sources';

function reading(id: string, title: string, group: string, summary: string, sections: ContentSection[], objectives: string[], exercise: string, quizTopic: string, relatedProblemIds: string[], sourceIds: SourceId[], premium = false): Lesson {
  const words = sections.flatMap(section => [section.body, ...(section.bullets || [])]).join(' ').trim().split(/\s+/).length;
  return { id, title, group, summary, sections, objectives, exercise, quizTopic, relatedProblemIds, sourceIds, premium, minutes: Math.max(3, Math.ceil(words / 200)) };
}

export const lowLevelDesignLessons: Lesson[] = [
  reading('introduction', 'From requirements to responsibilities', 'Foundations', 'Turn a product story into observable behavior, ownership, and one complete operation.', [
    { title: 'Begin with an operation, not a class list', body: `A low-level design interview asks how a program should behave when its objects collaborate. Start with one representative operation, such as placing a parcel into a locker. Identify the actor, inputs, successful result, and rejected situations. An object diagram cannot answer whether a large parcel fits a small compartment or whether a pickup code can be reused. Those questions belong in the operation contract before implementation details.

Separate stated requirements from assumptions. Perhaps packages are allocated within one facility, time is supplied explicitly, and pickup codes are opaque identifiers. Say which assumptions you will revisit if the interviewer changes scope. Do not invent remote payment, delivery routing, or distributed consensus simply because a familiar platform has those features. A bounded model lets you demonstrate a complete solution rather than scatter attention across an unfinished collection of services.` },
    { title: 'Assign ownership to the invariant', body: `Find the facts that must remain true after every accepted operation. A locker cannot contain two active parcels. A pickup receipt cannot release a different parcel. A reservation that has expired cannot be treated as current merely because the cleanup job has not run. These invariants suggest an owner that can inspect and update the relevant state together.

Write responsibilities as verbs. An allocator chooses a compatible compartment; a reservation records ownership and expiry; a clock supplies the current instant. Avoid creating a class for every noun in the prompt. A size may be a value rather than an independently managed object. Conversely, putting everything in one coordinator does not make the design cohesive. If the coordinator knows every field and manually changes them, the named objects are only bags of data and the invariant is still scattered.` },
    { title: 'Walk success and rejection through the boundary', body: `Trace allocation step by step: validate the request, observe the supplied time, remove logically expired occupancy, select a compartment, and record the reservation before returning a receipt. Then trace a failure, such as insufficient capacity. Explain which state remains unchanged and which result the caller receives. A rejected allocation should not consume a code or leave an invisible half-reservation.

Now challenge a retry. If the caller loses a successful response, can it recover the receipt without allocating another locker? The answer depends on whether the contract includes an operation identity and stores its outcome. A local array search is not automatically a retry-safe service. Label the reference implementation as a sequential model when it does not include database transactions or multiple processes. Its value is making behavior visible, not claiming production guarantees it cannot enforce.` },
    { title: 'Deliver a small vertical slice', body: `Prefer one complete use case with a readable constructor, a small public method, a result shape, and focused tests. Include an empty facility, an exact size match, a missing pickup code, and an expiry boundary. These examples expose decisions that an elaborate inheritance tree can hide. Use a controllable clock rather than sleeping in tests.

Explain the complexity using the actual representation. Scanning all compartments costs linear time in facility size; indexing availability by size can reduce repeated searching but adds bookkeeping. Copying a receipt prevents callers from changing internal ownership accidentally, yet copying also consumes memory. Keep such tradeoffs explicit. Finish by naming the next extension and the specific contract it affects. The strongest starting point is a working, scoped model whose assumptions another engineer can inspect and change.` },
  ], ['Translate a user operation into a success and rejection contract.', 'Choose an owner for each state invariant.', 'Demonstrate a complete, bounded use case before extending the model.'], 'Trace parcel allocation and pickup, including an expired code and a retry after a lost response.', 'object-modeling', ['parcel-lockers', 'lld-inventory-ledger'], ['fowler-tell', 'js-classes']),
  reading('object-modeling', 'Identity, values, and aggregate ownership', 'Foundations', 'Decide what needs identity and which state must change as one unit.', [
    { title: 'Distinguish an entity from a value', body: `An entity is distinguished by a stable identity across changes. A reservation can keep its identifier while its status changes from held to collected. A value is distinguished by its contents: two compatible size labels or two equal monetary amounts can be interchangeable within the contract. This distinction helps decide equality, replacement, and serialization without requiring a particular domain framework.

Do not infer identity from object reference equality alone. Two JavaScript objects loaded separately can represent the same reservation. Compare their explicit identifiers when that is the domain rule. Likewise, a plain object with matching fields does not necessarily have valid contents. Validate units, ranges, and required fields at the boundary. If an amount is expressed in integer cents, preserve that unit throughout the operation rather than silently mixing it with dollars or an unrounded fractional price.` },
    { title: 'Locate the consistency boundary', body: `An aggregate is a useful way to describe an owner that protects related state changes. For an inventory ledger, available units and active reservations cannot be maintained independently without a coordination rule. Reserving three units should reduce availability and create the matching reservation together. Releasing the same reservation twice must not add six units back.

This is a design boundary, not a requirement that every object be loaded in memory forever. A persistent implementation might enforce the boundary through a transaction, conditional update, and uniqueness constraint. A sequential teaching model can enforce it through a single method that completes before the next command. Name that difference. A diagram that puts two tables under one box does not make their writes atomic, and a private class field does not coordinate two application processes.` },
    { title: 'Protect ownership from accidental aliasing', body: `A public getter that returns the mutable internal reservation map gives callers a second path for changing state. They can bypass validation, release capacity without a receipt, or erase a reservation while its code still exists. Return a bounded read model, an immutable value, or a defensive copy according to the contract. Copying nested structures requires attention: a new outer array can still contain references to mutable inner records.

Do not treat every query as a design failure. A read-only availability view can be exactly what a caller needs. The useful principle is to keep business mutations with the owner while exposing intentional information. Ask whether a query describes state or forces the caller to reconstruct a business decision from internal fields. Those are different responsibilities, even when both use getters in the programming language.` },
    { title: 'Choose representations that preserve meaning', body: `Use an explicit identifier map for lookups and a separate ordering structure when order matters. A pickup code, reservation identifier, and locker identifier serve different purposes even if all are represented as strings. Document where each is unique and whether it may be reused. JavaScript Map accepts identifier strings such as constructor without inherited-property behavior, but its specification does not promise a particular constant-time hash implementation.

Show a small state table before and after each command. The ledger should conserve initial units across available, reserved, and committed totals. This is more informative than a class name alone. Include removal and terminal records in the memory model: retaining receipts supports retries, while unbounded retention eventually becomes a resource problem. The correct representation follows the required observations and lifecycle, not the desire to demonstrate every collection type.` },
  ], ['Separate stable identity from value equality.', 'Define a state owner and consistency boundary.', 'Prevent external mutation while retaining useful queries.'], 'Model five inventory units across reserve, commit, and release commands; state the conservation equation.', 'object-modeling', ['lld-inventory-ledger', 'parcel-lockers'], ['js-classes', 'pg-constraints', 'fowler-tell']),
  reading('design-principles', 'Cohesion and dependency direction', 'Foundations', 'Use change scenarios to judge boundaries instead of counting patterns.', [
    { title: 'Measure cohesion with a plausible change', body: `Cohesion means related responsibilities belong together. Ask what would change if a parking facility adds a weekend pricing rule while entry-ticket validation remains unchanged. If both concerns are interleaved across every method, the current boundary makes an ordinary change risky. A pricing policy can own that variation, while the parking session owns whether it is active or already closed.

One responsibility does not mean one line of code or one public method. Several operations may protect the same lifecycle and naturally belong together. Conversely, a method named processEverything can contain unrelated formatting, storage, charging, and state mutation. Judge responsibilities by the decisions they own and the reasons they evolve. Refactoring should make an actual requirement easier to implement, not merely produce a larger number of tiny files with indistinguishable names.` },
    { title: 'Direct dependencies toward useful contracts', body: `Business behavior should describe the capability it needs, such as loading a session by identity and atomically closing its current version. An infrastructure adapter can implement that capability using a database. A test adapter can implement the same observable outcomes with controlled failures. Construct the domain service with these collaborators instead of letting it discover a global database connection.

Dependency injection is the act of supplying a dependency; it does not require a container or framework. A constructor argument often makes mandatory dependencies clearer than a mutable setter. An injected collaborator is only useful when its contract includes meaningful semantics. If the repository exposes arbitrary SQL fragments and provider-specific errors, the abstraction has preserved the infrastructure coupling while adding another layer of names. Keep the interface small and shaped around the business operation.` },
    { title: 'Prefer composition when variation is independent', body: `A parking session can use a pricing policy without inheriting from a special weekend garage subclass. A cache can receive an eviction policy without turning every key type into a new cache class. Composition makes independently varying decisions easier to combine and test. It also allows a policy to remain a simple function when no state or lifecycle justifies a class.

Inheritance remains useful when the subtype can honor the complete parent contract. A subtype that rejects ordinary parent operations, changes units, or broadens failure behavior can break callers even if its methods have matching names. Examine actual substitution: run the same contract tests against each implementation. Do not introduce a strategy interface for a constant that will never vary; unnecessary abstraction can make a straightforward design harder to understand and maintain.` },
    { title: 'Refactor with behavioral evidence', body: `First record what the current operation does, including edge cases and error results. Move the pricing decision behind a collaborator while keeping the session lifecycle unchanged. Compare the same trace before and after the refactor. Test a zero-duration stay, exact billing-unit boundary, rejected second checkout, and a policy failure that must not close the ticket.

Avoid tests that enforce the internal call graph without a contractual reason. Requiring a private helper to be called exactly once can make a harmless implementation change fail. An external charge or notification may need a duplicate-effect assertion because it is observable; an internal arithmetic helper usually does not. Explain which coupling the refactor removed, what complexity it added, and how a future policy would be introduced. Good design principles are tools for preserving behavior under change, not automatic proof that the design is correct.` },
  ], ['Evaluate cohesion using concrete change scenarios.', 'Inject mandatory capabilities without requiring a framework.', 'Check substitution behavior and avoid speculative abstraction.'], 'Separate parking-session state from pricing policy, preserving exact cents and rejected duplicate checkout.', 'design-principles', ['parking-garage', 'lld-lru-cache'], ['fowler-di', 'fowler-tell', 'fowler-unit']),
  reading('interfaces', 'Contracts at object boundaries', 'Contracts and state', 'Specify outcomes, ownership, and failure semantics before choosing an adapter.', [
    { title: 'A method signature is only the beginning', body: `A reserve(identifier, quantity) signature does not say whether retries are allowed, whether quantity is measured in units, or whether insufficient stock changes state. Write the input domain, accepted outcome, rejected outcomes, and mutation rules alongside the signature. If a returned receipt contains a reservation identifier, explain whether the caller owns that value and how long it remains meaningful.

Consider a repository method called save. Does it insert or overwrite? Does it check a version? Can a timeout occur after the write commits? The caller cannot handle uncertainty correctly without answers. A good contract need not describe every database detail, but it must expose distinctions that change the next decision. Hiding every failure behind false is not simplicity if callers can no longer tell a business rejection from infrastructure unavailability.` },
    { title: 'Separate commands from intentional observations', body: `A command asks the owner to perform a state change, while a query asks for a view. This distinction helps make mutation paths visible, but it is not a universal ban on returning a command result. Returning a newly created receipt avoids forcing the caller to perform a race-prone second lookup. Specify the view associated with that result and whether it represents the committed operation.

For a cache, get may intentionally update recency even though it looks like a read. State that behavior rather than pretending the method is observationally pure. A peek operation can provide a non-touching view when callers need it. For a file catalog, listing returns a sorted set of child names, not a live mutable map. Such choices belong in the contract because they determine what a test, adapter, or alternative implementation must preserve.` },
    { title: 'Inject capability and lifecycle together', body: `Supplying a clock function allows deterministic expiry tests, but you must also specify what its value means: integer milliseconds, monotonic sequence, or a wall-clock timestamp. A supplied random identifier generator may fail or collide. A repository may need a transaction handle with a defined lifetime. Dependency injection does not remove these questions; it makes their answers available at a deliberate boundary.

Use JavaScript classes or functions to demonstrate the protocol, while acknowledging that a matching method name is not runtime validation of the whole contract. Private fields protect access in a particular language; they are not a replacement for authorization, validation, or concurrency control. A test double should honor valid-input and outcome semantics, not conveniently accept every request. Otherwise tests certify a collaborator that cannot exist in the real environment.` },
    { title: 'Prove interchangeable implementations', body: `Create a contract suite that runs the same operation traces against each adapter. Include duplicate identities, missing records, exact version matches, stale versions, and allowed empty results. Keep infrastructure-specific tests for transaction behavior, durability, and provider errors separately. A memory adapter can verify logical transitions but cannot prove that PostgreSQL locks the intended rows.

Explain how resources are acquired and released. An adapter with a shared connection pool has a different lifecycle from a per-operation transaction. Avoid leaking a transaction object into unrelated domain methods merely to reuse one signature. When you introduce a new adapter, first show the semantic equivalence required by callers, then the additional integration evidence needed. A boundary is useful when it reduces uncertainty for clients, not when it simply replaces a concrete class name with an interface name.` },
  ], ['Specify contract details beyond parameter types.', 'Distinguish intentional observations from hidden mutation.', 'Validate adapter equivalence with shared behavioral tests.'], 'Define reserve and load contracts for a ledger, including stale versions and a timeout after a committed change.', 'interfaces', ['parking-garage', 'lld-inventory-ledger'], ['fowler-di', 'js-classes', 'fowler-unit']),
  reading('state-machines', 'Explicit state transitions', 'Contracts and state', 'Make lifecycle rules inspectable and illegal changes visible.', [
    { title: 'Enumerate states and events separately', body: `A document approval request might be draft, submitted, approved, or cancelled. Events such as submit, approve, and cancel describe requested changes. State and event are different concepts: approved is a condition, while approve is an action that may be rejected. List the permitted transitions before writing nested conditionals.

Choose one initial state and identify terminal states. Decide whether cancellation is allowed after approval and whether a rejected approval can be retried. Those are product choices, not consequences of naming a class StateMachine. A small transition table is often sufficient. The W3C state-chart specification describes richer concepts such as nested states and run-to-completion processing; a teaching table does not implement that entire standard and should not claim to support its history or parallel-state semantics.` },
    { title: 'Treat a transition as one owned operation', body: `A transition checks the current state, verifies the event preconditions, and records the next state together. If approve requires submitted, do not expose separate public setters that let a caller bypass the check. A version can make the expected state observation explicit: an operation based on version two should not overwrite version three silently.

Rejection is also an observable outcome. Return an illegal-transition result without changing state or advancing the version. If the contract records attempts in an audit log, distinguish that log append from the domain transition itself. Consider failure during a side effect. A notification error should not leave an undocumented mixture of approved state and success-shaped response. State clearly which change is authoritative and how notification work will be retried or reported.` },
    { title: 'Define repetition, ordering, and history', body: `An operation identity can let a retry recover its previous result. Bind it to the same event and parameters so reuse for another request is a conflict, not accidental approval. Decide whether the stored result is replayed even if the object has since moved forward. Retaining a historical receipt is often correct, whereas reporting the current state as if it were the original response changes the retry contract.

Order commands explicitly in a sequential model. A history of requested events differs from a history of accepted transitions; replaying rejected commands may reproduce errors without changing state. A turn-based game likewise needs the actor, board position, and expected turn in its move contract. Recording only the final board cannot explain which move was rejected or why a player lost the right to move.` },
    { title: 'Test edges in the transition graph', body: `Test every permitted transition and representative forbidden edges. Include repeated submit, approve before submit, cancel from a terminal state, and a stale-version operation. Assert the exact before-and-after state and version. A test that checks only the final label can miss an intermediate illegal change or a version increment on rejection.

Keep the model small enough that traces can be inspected by hand. A table makes allowed edges obvious; state objects become useful when each state owns substantial distinct behavior. Neither representation makes persistence atomic automatically. In a real service, protect the transition at the authoritative storage boundary and record any required outbox work consistently. The interview goal is a lifecycle another engineer can reason about, including the inconvenient paths, rather than a vocabulary-heavy implementation that works only for the happy sequence.` },
  ], ['Separate lifecycle states from requested events.', 'Reject invalid or stale transitions without partial mutation.', 'Test transitions, history, and retry semantics explicitly.'], 'Draw an approval lifecycle, then trace a stale approval and an idempotent retry after cancellation.', 'state-machines', ['board-game', 'lld-workflow-engine'], ['w3c-scxml', 'pg-isolation']),
  reading('error-contracts', 'Failures are part of the object API', 'Contracts and state', 'Make rejections, uncertain outcomes, and unexpected faults distinguishable.', [
    { title: 'Separate invalid data from a rejected operation', body: `Malformed input and a valid request that cannot currently succeed are different situations. A negative inventory quantity violates the input domain. Requesting three valid units when only two remain is a business rejection. A well-defined operation reports the latter deliberately and leaves state unchanged. Boundary validation should reject the former rather than quietly reinterpret it as zero.

Keep result categories small but meaningful. A reserve operation might return reserved, insufficient, or identity-conflict. A storage adapter might throw an infrastructure error when it cannot determine the outcome. Do not collapse all these situations into an empty list or a boolean if callers need a different response for each. Also avoid returning arbitrary provider text as a stable public error contract; map known cases deliberately and preserve diagnostic details at the appropriate logging boundary.` },
    { title: 'Order validation before irreversible mutation', body: `Compute and validate the next state before publishing it. A file-catalog write should verify the parent directory and target kind before replacing the stored file. A checkout should validate the session and pricing result before marking the ticket closed. If the operation can fail after part of the work, identify the commit boundary and the available recovery procedure.

In-memory rollback is not always a safe answer. Releasing a lock, sending an email, or charging an external provider may already have produced an observable effect. A compensating operation is another operation that can fail, not a time machine. For an educational model, keep effects deterministic and local. Then explain the additional persistent receipt, transactional outbox, or reconciliation mechanism needed when the same domain behavior crosses a real process or provider boundary.` },
    { title: 'Represent uncertainty rather than fabricating success', body: `A timeout can mean the command was never applied or that it committed before its response was lost. A caller should recover using a stable operation identity or an authoritative status query. Retrying blindly can allocate another resource; marking the operation successful without evidence can lose the resource entirely. State the uncertainty in the result contract instead of hiding it behind a broad catch.

An expected not-found outcome should be explicit when absence is normal, while an unavailable datastore should remain an error. Logging every expected business rejection at an emergency severity creates noise and can expose sensitive inputs. Conversely, silently dropping unexpected faults prevents diagnosis. Describe what the user sees, what operators can inspect, and what fields must not be included. The behavior contract and the observability contract support each other but are not identical.` },
    { title: 'Test non-mutation and recovery sequences', body: `For each rejection, compare a snapshot before and after the operation. Repeating an invalid transition should not consume stock, advance a workflow version, or change cache recency unless that behavior is documented. Test that a later valid command still succeeds after the failure. This catches state corruption that a single error assertion misses.

Use injected failures at named boundaries: before storage, during conditional update, after commit, and during downstream delivery. A fake that always succeeds cannot establish recovery behavior. Keep expected errors separate from defects in the test harness itself. Finally, explain how error codes evolve. Adding a new rejection category can affect every caller that assumed only success and not-found, so compatibility belongs in the interface discussion. Clear failure behavior is an essential part of a finished design, not an optional final paragraph.` },
  ], ['Distinguish malformed input, business rejection, and uncertain infrastructure outcomes.', 'Identify the commit boundary before choosing recovery.', 'Verify rejected operations do not corrupt subsequent behavior.'], 'Specify file-write results for missing parents, directory conflicts, and successful replacement; trace every state change.', 'error-contracts', ['lld-file-catalog', 'lld-workflow-engine'], ['http-semantics', 'pg-constraints', 'fowler-unit']),
  reading('concurrency', 'Concurrency and shared state', 'Coordination and representation', 'Protect the whole invariant at the boundary where writers actually meet.', [
    { title: 'A valid observation can become stale', body: `Two callers can both observe one free parking space before either reserves it. Each local check can be correct and the combined history can still violate exclusive ownership. Identify the check and mutation that must be coordinated. Adding a second check without synchronization only moves the race to a narrower interval.

JavaScript does not make every application operation atomic merely because one event loop executes callbacks. An await can separate a read from its later write, and another operation may change the state in between. Workers, multiple server processes, and database writers add further concurrency boundaries. A synchronous reference trace is useful for lifecycle rules, but it contains no actual overlapping operations. Do not present its passing fixtures as evidence that a production reservation protocol excludes competing writers.` },
    { title: 'Choose a coordination mechanism from the invariant', body: `A conditional update can compare the expected version and advance it only when the stored version still matches. A database uniqueness constraint can reject two active owners of a resource when the schema expresses that rule correctly. Row locking can coordinate updates to existing rows within a transaction. These mechanisms have different observation and failure semantics; none should be named without showing the protected operation.

A process-local mutex coordinates only participants sharing that mutex. It does not protect another server or a database client. Likewise, locking one existing row does not automatically protect every possible row matching an absent predicate. In PostgreSQL, lock modes and isolation levels determine the relevant behavior, and serialization failures may require retrying the transaction. Use the cited documentation for the actual version rather than treating a generic lock icon as an implementation.` },
    { title: 'Keep critical sections bounded and ordered', body: `Do the minimum state inspection and update under the coordination mechanism. Do not hold a resource lock while making an unrelated slow network call if the invariant can be protected by recording intent and completing the external step separately. When several resources must be acquired, choose a stable acquisition order to reduce deadlock risk and define a bounded response to contention.

Lock ordering does not eliminate every deadlock or failure. A transaction may be aborted, a client can disconnect, or a retry can encounter a changed state. A timeout is not proof that ownership was released. In a persistent design, inspect the transaction and provider boundaries; in a leased design, consider stale owners and fencing. Keep those concerns proportional to the prompt. Introducing distributed leases for a single-threaded local collection adds complexity without protecting an actual shared boundary.` },
    { title: 'Test histories, not just isolated method calls', body: `Create a deterministic competing-writer test by pausing two operations after their initial observation and then allowing their updates to race. Assert one ownership result, conserved capacity, and visible rejection or retry behavior for the loser. Integration tests must use the real transactional mechanism when that is the guarantee being evaluated.

For optimistic versions, include a successful change, a stale write, and a retry using the original operation identity. For multiple locks, force opposite request orders and verify the configured policy. Record which tests are simulated sequential histories and which involve actual overlap. This distinction is especially important for an interview demo: a clean state-machine implementation is valuable, but its correctness argument must match the execution model. Explain both the protected invariant and the evidence needed before expanding the design to more writers.` },
  ], ['Locate the check-and-update race and authoritative coordination boundary.', 'Compare conditional writes, constraints, and locks without overclaiming.', 'Distinguish simulated histories from real concurrent integration tests.'], 'Write a schedule in which two writers read version zero; explain the conditional update that permits only one commit.', 'concurrency', ['rate-limiter', 'lld-workflow-engine', 'parking-garage'], ['pg-locks', 'pg-isolation', 'pg-constraints'], true),
  reading('collections', 'Collections, ordering, and bounded state', 'Coordination and representation', 'Make key equality, recency, and retention rules part of the design.', [
    { title: 'Choose a collection from the required observations', body: `An identifier lookup and an ordered traversal are different operations. A reservation map supports finding a specific receipt, while an ordered list may support selecting the oldest active reservation. If one collection does both jobs, explain how it maintains the required order. Do not assume insertion order is automatically the same as access recency.

In JavaScript, Map supports explicit keys without inherited-property collisions from a plain object. A key such as constructor should remain an ordinary identifier when the domain allows it. The language specifies average sublinear access for Map, not a mandated constant-time hash-table implementation. State a hash-table model when using expected constant-time costs, and include the cost of maintaining any separate list, sorting results, or producing a defensive copy for callers.` },
    { title: 'Specify the complete cache policy', body: `For a least-recently-used cache, define which operations touch recency. A successful get usually makes a key most recent. A missing get cannot refresh an absent record. Updating an existing key may both replace its value and move it to the newest position. Capacity zero should have an explicit behavior rather than accidentally retaining the first item.

Separate eviction from expiration. LRU removes entries because of capacity pressure; a TTL invalidates entries because of age. One does not imply the other. A teaching LRU with no clock is not a freshness-aware profile cache. Decide whether put reports an evicted entry and whether reading a cached null is distinguishable from a miss. A tagged hit result can preserve that distinction without overloading the value itself.` },
    { title: 'Account for lifecycle and retained history', body: `Bounded active state is not the same as bounded total memory. An inventory ledger can release every reservation while retaining all operation receipts forever. A rate limiter can keep an empty counter for every client it has ever seen. A directory catalog can preserve tombstones after deletion. Identify the retained structures separately and choose cleanup rules consistent with retries, audit, and lookup behavior.

Expiry should be defined at an exact boundary. If a reservation expires at time ten, specify whether a request at time ten is already too late. Lazy cleanup can be correct when every relevant operation first applies logical expiry; an asynchronous cleanup job alone cannot make expired occupancy valid until the job runs. Inject time in tests and distinguish a monotonic local tick from a globally comparable timestamp.` },
    { title: 'Pick the simplest adequate representation', body: `For a cache capped at thirty-two entries, an array with linear recency searches can be a clear interview implementation. Its cost is linear in capacity per operation and its storage is bounded by that capacity. A map plus a doubly linked list can make recency updates efficient under the assumed lookup model, but it introduces node ownership and unlinking invariants.

Explain why you choose one representation and what would justify changing it. Test eviction after a read, replacement of an existing value, missing keys, zero capacity, and identifiers that look like object properties. Verify snapshots do not expose mutable internals. Then consider the deployment boundary: a local cache is an optimization in one process, not a distributed ownership service. The collection should satisfy a precise local contract before its shape is generalized to a larger system.` },
  ], ['Separate key lookup from ordering and recency.', 'Define eviction, misses, zero capacity, and cleanup boundaries.', 'Analyze auxiliary state and defend a bounded representation.'], 'Trace a capacity-two LRU through put A, put B, get A, put C, and get B, including the recency order.', 'collections', ['lld-lru-cache', 'rate-limiter'], ['js-map', 'js-classes', 'fowler-unit']),
  reading('patterns', 'Patterns as constrained design choices', 'Coordination and representation', 'Use a pattern only when it simplifies a demonstrated change or invariant.', [
    { title: 'Name the variation before the pattern', body: `A strategy is useful when a decision varies independently, such as selecting a parking pricing rule. An observer is useful when several consumers react to a change without the owner knowing their concrete implementations. A composite is useful when leaf and container operations share meaningful semantics. These are reasons to introduce a structure, not decorations that every interview design must include.

Begin with the simplest implementation and describe one actual extension. If pricing is a fixed integer amount, a function may be sufficient. If it has multiple configurable policies and independent tests, a supplied policy object can improve clarity. Do not create a subclass for every combination of vehicle, payment method, facility, and promotion; independent variation can produce a rapidly growing inheritance tree with unclear ownership.` },
    { title: 'A composite needs consistent semantics', body: `A directory and a file both have a name, but they do not necessarily support every same operation. Reading file content and listing directory children are different capabilities. A common node representation can support traversal while deliberate kind checks reject inappropriate operations. Forcing both kinds to implement meaningless methods that always throw can weaken rather than improve substitution.

Specify how deletion works for a nonempty directory and whether parent directories are created implicitly. A small file catalog can reject deletion until its children are removed. A recursive deletion command is a different, potentially destructive contract. Decide whether a path is normalized at the boundary and which identifiers are valid. A pattern diagram cannot resolve these details, but their answers determine whether the composite behavior is usable and testable.` },
    { title: 'Observers and commands create failure boundaries', body: `If an observer fails after a reservation commits, should other observers run, should the operation be retried, or should the caller receive a warning? Specify the delivery and retry policy rather than assuming a callback list guarantees reliable notification. In a persistent service, recording an outbox entry can separate durable intent from delivery. An in-memory observer list alone cannot survive a process crash.

A command object can hold the data needed to request an operation, making traces and replay easier. It is not automatically reversible. Undoing a workflow approval after downstream action may require a new compensating command with its own authorization and failure handling. Distinguish recording intent, recording accepted changes, and recording externally completed effects. Otherwise the design may promise undo for an effect it no longer controls.` },
    { title: 'Evaluate the cost of indirection', body: `Every new collaborator adds construction, lifecycle, and semantic obligations. Compare the pattern-based version with a straightforward conditional or function. Does it isolate a real change, support a needed adapter, or make an invariant easier to enforce? If not, keep the smaller design. Framework-independent constructor wiring is often enough for a bounded exercise.

Test each variation through the same public contract. Include a pricing policy that returns a rejected result, a directory traversal that reaches a leaf, and an observer that fails at a named boundary. Keep implementation details out of tests unless they protect a required side effect or ordering rule. Finish by explaining the extension that would motivate the next abstraction. Demonstrating restraint is part of low-level design: a readable solution that handles the stated behavior is stronger than a catalog of patterns whose interactions are unfinished.` },
  ], ['Connect a pattern to a specific variation or invariant.', 'Identify failure and substitution issues hidden by a diagram.', 'Compare the pattern with a simpler behavioral equivalent.'], 'Decide which file-catalog operations can share a node abstraction and which must reject the wrong node kind.', 'design-principles', ['lld-file-catalog', 'parking-garage'], ['fowler-di', 'fowler-tell', 'fowler-unit']),
  reading('persistence', 'Persistent ownership and durable invariants', 'Evidence and evolution', 'Map object rules to transactions and constraints without leaking storage details everywhere.', [
    { title: 'Separate the model from its stored representation', body: `A reservation object and a database row can represent the same identity without sharing every field or method. The domain model owns the lifecycle rule; the repository maps the state to storage. Avoid making every business operation depend on table names and query fragments merely because persistence is required.

The repository contract must still expose relevant guarantees. Loading a record and later saving it without a version check permits a lost update. A method that conditionally changes a known version and returns a conflict is a different operation. Specify whether a returned object is detached from storage and whether the operation can fail after commitment. A simple memory adapter is useful for domain tests, but it cannot stand in for actual transaction isolation or crash durability when those are the promises under examination.` },
    { title: 'Enforce the invariant where writes converge', body: `Application validation improves errors, but concurrent writers can bypass the observations on which that validation relied. A database uniqueness constraint can enforce a modeled identity rule for all writers. A check constraint can enforce row-level relationships such as a nonnegative count. Constraints should be shaped around the actual stored state and legal transitions rather than added as generic safety labels.

PostgreSQL check constraints are not a general mechanism for asserting arbitrary cross-row conditions. Use the appropriate keys, relationships, transaction protocol, or other supported mechanism for the required invariant. A nullable column also requires careful reasoning because unknown values do not behave like ordinary true or false in SQL checks. The application and storage layers can defend the same business rule at different boundaries without pretending that one form of validation replaces every other.` },
    { title: 'Handle compound changes and external effects', body: `Committing an inventory reservation may update the reservation status and the available-versus-sold accounting in one transaction. Sending a downstream notification is another boundary. If the process crashes after commit, the domain change must not be repeated merely because notification was incomplete. A stored operation receipt and transactional outbox can make the recovery path explicit when the prompt includes durable asynchronous delivery.

Do not hold a database transaction open across an uncontrolled external payment call without understanding timeout and locking consequences. Alternatively, model an intermediate pending state and reconcile a provider outcome using a stable identity. Neither design is universally best; the required invariants and allowed temporary states determine the choice. Explain the failure window you close and any uncertainty that remains instead of drawing one large transaction box around unrelated systems.` },
    { title: 'Test persistence as a separate guarantee', body: `Run domain traces against a memory adapter to check transition rules quickly. Then use integration tests to verify the real uniqueness rule, conditional update, transaction rollback, and restart behavior. Force competing operations when exclusive ownership is the requirement. A test that reloads an object from the same in-memory map has not established persistence across a process failure.

Treat migrations as changes to a stored contract. Old rows, old readers, and new writers may coexist during rollout. Adding a mandatory field can break loading historic records unless the migration and defaults are planned. Keep the serialization version or mapping deliberate and verify backward-compatible reads when required. The model should remain understandable without infrastructure details, while the persistence evidence must match the actual storage mechanism. Both layers are necessary for a reliable finished design.` },
  ], ['Specify repository guarantees instead of exposing arbitrary storage operations.', 'Choose storage constraints appropriate to the invariant.', 'Separate domain tests from real transaction and restart evidence.'], 'Describe a persistent inventory commit and notification recovery path, including a crash after the database commit.', 'concurrency', ['lld-inventory-ledger', 'lld-workflow-engine'], ['pg-constraints', 'pg-isolation', 'pg-locks', 'outbox']),
  reading('testing-designs', 'Testing contracts and state histories', 'Evidence and evolution', 'Use deterministic traces, invariants, and integration evidence to challenge the design.', [
    { title: 'Choose a useful unit of behavior', body: `A unit test can exercise a function, a class, or a small group of collaborating objects. The important question is whether the boundary makes a behavior understandable and its failures diagnosable. Do not assume every collaborator must be mocked or that every class requires an isolated test file. A small object cluster may be the natural owner of one invariant.

Use test doubles where controlling time, failures, or external effects is valuable. Keep a real pure pricing policy in a session test when that improves confidence without making the test slow or nondeterministic. A fake repository should preserve the meaningful contract, including duplicate identities and stale versions. A fake that ignores these cases can make a flawed domain operation appear correct. Describe which dependency behavior the test controls and which behavior it actually validates.` },
    { title: 'Test sequences and intermediate observations', body: `Stateful defects often need more than one command. Reserve, release, release again can reveal duplicated capacity. Put A, put B, get A, put C exposes recency maintenance. Submit, reject a stale approval, and approve with the correct version distinguishes non-mutation from mere error reporting. Record the expected result of every step, not just the final state.

Include exact boundaries: zero capacity, expiry at the supplied time, empty input, a missing identifier, and a terminal transition. Build expected fixtures independently of the implementation under test. Generating expected results by calling the reference code certifies only that the code agrees with itself. Keep input mutation checks when the harness promises not to modify its caller-owned event list, and repeat calls on the same reference function to detect hidden global state.` },
    { title: 'Add invariant and oracle checks', body: `For inventory, assert conservation after every command: available plus reserved plus committed units equals initial capacity. For an LRU, assert no duplicate keys and entry count within capacity. For a workflow, versions advance only on accepted transitions and recorded retries reproduce their historical result. These assertions can detect failures across many generated traces without hard-coding every intermediate state.

Use a simpler independent model as an oracle for bounded inputs. An array-based cache model can check a linked-list implementation, while an exhaustive small state graph can check transition behavior. State the domain limits of the oracle and choose deterministic random seeds so a failing trace can be reproduced. A large test count is not a correctness proof; it is evidence that complements a clear invariant and a review of the implementation's branches.` },
    { title: 'Label the evidence honestly', body: `Sequential JavaScript traces verify local state semantics, not simultaneous database writers. A stubbed provider verifies the request and response contract, not a live service's reliability. A restart test using a real database verifies a different property from reloading a page. Keep these distinctions visible in the test plan and any user-facing report.

After a refactor, rerun existing contract tests and focused integration tests that cover the changed boundary. Prefer assertions about observable results over incidental method order unless ordering itself is required. Preserve a minimal failing trace when fixing a bug and verify the exact requirement rather than a convenient proxy. Finally, name what remains unverified: production load, multi-process contention, provider uncertainty, or editorial accuracy. Honest evidence makes a design easier to trust and improve than a broad claim that every test passed somewhere.` },
  ], ['Select a behavioral test boundary and meaningful doubles.', 'Verify stateful traces, boundaries, and non-mutation.', 'Combine invariant checks with honest labels for integration evidence.'], 'Write an independent trace oracle for an LRU and a conservation assertion for an inventory ledger.', 'testing-designs', ['lld-lru-cache', 'lld-inventory-ledger', 'board-game'], ['fowler-unit', 'js-classes']),
  reading('design-walkthrough', 'Defend one complete object design', 'Evidence and evolution', 'Connect the brief, model, trace, implementation, and evidence in one explanation.', [
    { title: 'Restate the observable contract', body: `Start the walkthrough by naming the bounded product operation and its assumptions. A local file catalog may support explicit directory creation, file replacement, direct-child listing, and nonrecursive removal. That is different from an operating-system filesystem with permissions, symbolic links, streaming writes, and crash recovery. Say which behavior is included before selecting data structures.

List the public outcomes and the state they permit. A missing parent must not create a hidden partial path. A file cannot be treated as a directory simply because its identifier is valid. Replacing content should preserve the node kind and identity rule. These examples make the scope concrete and provide acceptance criteria. Keep a small requirement table available so later implementation choices can be traced back to what callers actually need.` },
    { title: 'Explain ownership and collaborators', body: `Show which object owns the node index and which methods are the allowed mutation paths. The path parser can validate and split a path without owning directory state. A storage adapter, if needed, handles persistence rather than deciding which nodes are legal children. A read model presents child names in the documented order.

Draw a compact diagram of capabilities and ownership, then explain a rejected operation through it. Do not make the diagram larger than the implementation can justify. If a policy is a pure function, depict it as a capability rather than inventing an inheritance hierarchy. If a method needs several owners to coordinate, identify the consistency boundary and show the transaction or conditional-write contract needed. Naming collaborators is useful only when their interaction preserves the required behavior.` },
    { title: 'Trace the awkward history', body: `Walk through create-directory, write-file, replace-file, list-directory, and attempt-to-remove a nonempty directory. State the returned result and the index contents after each command. Then try writing into a missing parent and deleting the root. These inconvenient paths often expose more about ownership than a successful first write.

Challenge retries and concurrency separately. A repeated write with identical content can be naturally idempotent under the stated local contract, while creating a directory that already exists may return an explicit exists result. A concurrent persistent implementation needs additional coordination; the sequential trace alone does not provide it. If the interviewer changes the requirement to recursive removal, explain the new failure and authorization boundary rather than slipping it into an existing method without updating its contract.` },
    { title: 'Close with complexity and evidence', body: `Account for path parsing, collection lookup, child enumeration, sorting, and output size. A naive direct-child listing can scan the whole index, while a maintained child index improves reads at the cost of update bookkeeping. Built-in JavaScript sorting has no specified implementation complexity; qualify any comparison-sort model you use. Include returned arrays and retained receipts in the space discussion.

Show independent fixtures, input immutability, repeated calls, and a small oracle when available. Explain which code runs in the browser model and which guarantees require actual infrastructure tests. Avoid converting a passing example count into a hiring-readiness or production-safety claim. Finish with one justified extension and one remaining limitation. A complete walkthrough makes the model executable and criticizable while preserving its boundaries, which is more useful than presenting a polished diagram with unresolved behavior behind every arrow.` },
  ], ['Trace requirements to ownership and implementation.', 'Explain successful and rejected histories with exact observations.', 'Defend complexity, verification, and explicitly scoped extensions.'], 'Present the file-catalog design in five minutes, then change removal to recursive deletion and explain what must change.', 'testing-designs', ['lld-file-catalog', 'lld-workflow-engine'], ['fowler-tell', 'fowler-unit', 'js-map']),
];
